import json, time, urllib.parse, urllib.request, urllib.error
UA="opencode-vault-image-fetcher/1.0 (educational Obsidian vault)"
def api(p,tries=5):
    p=dict(p); p["format"]="json"
    u="https://commons.wikimedia.org/w/api.php?"+urllib.parse.urlencode(p)
    d=10
    for i in range(tries):
        try: return json.load(urllib.request.urlopen(urllib.request.Request(u,headers={"User-Agent":UA}),timeout=60))
        except urllib.error.HTTPError as e:
            if e.code in (429,503) and i<tries-1: time.sleep(d); d*=2; continue
            raise
for q in ['G-spot','"G spot" anatomy','Gräfenberg','vagina diagram anatomy','female pelvis sagittal section anatomy']:
